import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { IDNAError, encode as idnaEncode, decode as idnaDecode, ulabel, valid_label_length } from './lib/idna.mjs';
import { bytesRepr } from './lib/pyfmt.mjs';

const DEPRECATION_MSG = 'DeprecationWarning: Transitional processing has been removed from UTS #46. The transitional argument will be removed in a future version.';

function main() {
  const prog = basename(process.argv[1]);
  const args = parseArgs(process.argv.slice(2), prog);
  const domain = args.domain;
  const mode = args.mode;
  const transitional = args.transitional;
  const strict = args.strict;

  const first_label = domain.split('.')[0];

  if (mode === 'encode' || mode === 'both') {
    if (transitional) {
      console.error(`test8.py:21: ${DEPRECATION_MSG}`);
    }
    let encoded = null;
    try {
      encoded = idnaEncode(domain, { transitional, strict });
      console.log(bytesRepr(encoded));
    } catch (e) {
      if (e instanceof IDNAError) {
        console.log('encode_error: ' + e.message);
        encoded = null;
      } else {
        throw e;
      }
    }
    if (first_label && encoded !== null && encoded.length > 0) {
      if (transitional) {
        console.error(`test8.py:30: ${DEPRECATION_MSG}`);
      }
      try {
        console.log(ulabel(idnaEncode(first_label, { transitional, strict })));
      } catch (e) {
        // bare except: swallow all errors silently
      }
    }
  }

  if (mode === 'decode' || mode === 'both') {
    try {
      console.log(idnaDecode(domain, { strict }));
    } catch (e) {
      if (e instanceof IDNAError) {
        console.log('decode_error: ' + e.message);
      } else {
        throw e;
      }
    }
  }

  if (first_label) {
    try {
      console.log(valid_label_length(first_label) ? 'True' : 'False');
    } catch (e) {
      // bare except: swallow all errors silently
    }
  }
}

main();

