// Replicates Python 3.12+ argparse behavior for this exact parser:
//   add_argument('--domain', type=str, required=True)
//   add_argument('--mode', type=str, required=True,
//                choices=['encode', 'decode', 'both'])
//   add_argument('--transitional', type=bool, required=False, default=False)
//   add_argument('--strict', type=bool, required=False, default=False)
// plus the automatic -h/--help.

import { strRepr } from './pyfmt.mjs';

const TEXT_WIDTH = 78; // terminal width 80 minus 2

const LONG_OPTIONS = ['--help', '--domain', '--mode', '--transitional', '--strict'];
const MODE_CHOICES = ['encode', 'decode', 'both'];

// A token starting with '-' counts as a value only if it is exactly '-'
// or looks like a negative number.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOptionString(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER_RE.test(token)) return false;
  return true;
}

// Greedy word-wrap of the usage line, mirroring argparse's HelpFormatter:
// pack parts so each line (including the indent) stays <= TEXT_WIDTH chars.
function formatUsage(prog) {
  const prefix = `usage: ${prog} `;
  const parts = [
    '[-h]',
    '--domain DOMAIN',
    '--mode {encode,decode,both}',
    '[--transitional TRANSITIONAL]',
    '[--strict STRICT]',
  ];
  const indent = ' '.repeat(prefix.length);

  const lines = [];
  let line = [];
  let lineLen = prefix.length - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > TEXT_WIDTH && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));

  // First line carries the real prefix instead of the blank indent.
  lines[0] = prefix + lines[0].slice(indent.length);
  return lines.join('\n') + '\n';
}

function formatHelp(prog) {
  return (
    formatUsage(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help'.padEnd(24) + 'show this help message and exit\n' +
    '  --domain DOMAIN\n' +
    '  --mode {encode,decode,both}\n' +
    '  --transitional TRANSITIONAL\n' +
    '  --strict STRICT\n'
  );
}

function printHelpAndExit(prog) {
  process.stdout.write(formatHelp(prog));
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(formatUsage(prog));
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// argv: process.argv.slice(2). Returns { domain, mode, transitional, strict }.
// transitional/strict are JS booleans computed as valueString.length > 0,
// replicating Python's bool(str) quirk for type=bool.
export function parseArgs(argv, prog) {
  const result = { domain: undefined, mode: undefined, transitional: false, strict: false };
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    // '--' separator: it and everything after it are unrecognized here,
    // since this parser defines no positionals.
    if (token === '--') {
      for (let j = i; j < argv.length; j++) extras.push(argv[j]);
      break;
    }

    if (token.startsWith('--')) {
      let name = token;
      let explicitValue = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        explicitValue = token.slice(eq + 1);
      }

      let matched = null;
      if (LONG_OPTIONS.includes(name)) {
        matched = name;
      } else {
        const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
        if (candidates.length === 1) {
          matched = candidates[0];
        } else if (candidates.length > 1) {
          errorAndExit(prog, `ambiguous option: ${token} could match ${candidates.join(', ')}`);
        } else {
          extras.push(token);
          i++;
          continue;
        }
      }

      if (matched === '--help') {
        printHelpAndExit(prog);
      }

      let value;
      if (explicitValue !== null) {
        value = explicitValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOptionString(next)) {
          errorAndExit(prog, `argument ${matched}: expected one argument`);
        }
        value = next;
        i++;
      }

      if (matched === '--domain') {
        result.domain = value;
      } else if (matched === '--mode') {
        if (!MODE_CHOICES.includes(value)) {
          errorAndExit(
            prog,
            `argument --mode: invalid choice: ${strRepr(value)} ` +
              `(choose from ${MODE_CHOICES.map(strRepr).join(', ')})`,
          );
        }
        result.mode = value;
      } else if (matched === '--transitional') {
        result.transitional = value.length > 0;
      } else if (matched === '--strict') {
        result.strict = value.length > 0;
      }
      i++;
      continue;
    }

    if (token === '-h') {
      printHelpAndExit(prog);
    }

    // Unknown short option, '-', a negative number, or a stray positional:
    // all collect as unrecognized arguments.
    extras.push(token);
    i++;
  }

  const missing = [];
  if (result.domain === undefined) missing.push('--domain');
  if (result.mode === undefined) missing.push('--mode');
  if (missing.length > 0) {
    errorAndExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return result;
}

